/* R1365 — Community Member promotions, events and reviewed promotional media */
(()=>{'use strict';
 const API='https://franklin-navigator-membership.onrender.com',root=document.querySelector('[data-member-profile-root]');if(!root)return;
 const n=(t,x,c)=>{const e=document.createElement(t);if(x!==undefined)e.textContent=x;if(c)e.className=c;return e};
 const qs=s=>document.querySelector(s),enc=encodeURIComponent;
 const labels={COUPON:'Coupon',SPECIAL:'Special',SALE:'Sale',PROMOTION:'Promotion',EVENT:'Event',COUPON_GRAPHIC:'Coupon graphic',SALE_GRAPHIC:'Sale graphic',PROMOTIONAL_GRAPHIC:'Promotional graphic',PROMOTIONAL_FLYER:'Promotional flyer',EVENT_FLYER:'Event flyer'};
 const state={profileId:'',active:false,promotions:[],media:[],editing:null,busy:false};
 async function req(path,{method='GET',body,headers}={}){const r=await fetch(API+path,{method,credentials:'include',cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(headers||{})},body:body?JSON.stringify(body):undefined});let o={};try{o=await r.json()}catch{}if(!r.ok){const e=new Error(o?.message||o?.error?.message||'We could not complete that promotion request.');e.code=o?.error?.code||o?.error||('HTTP_'+r.status);throw e}return o}
 function status(text,kind=''){let p=qs('[data-r1365-promo-status]');if(!p){p=n('p','', 'r37-status');p.dataset.r1365PromoStatus='1';panel()?.prepend(p)}p.className='r37-status'+(kind?' '+kind:'');p.textContent=text}
 function panel(){return qs('[data-r1365-promotions-panel]')}
 function selectedProfile(){const s=qs('#member-profile-selection');return s?.value||new URLSearchParams(location.search).get('profile')||''}
 async function syncEligibility(){const id=selectedProfile();if(!/^FR-[A-Z0-9]+-[A-Za-z0-9][A-Za-z0-9._-]{2,100}$/.test(id))return false;state.profileId=id;let me;try{me=await req('/api/accounts/me')}catch{return false}const linked=(me.profileLinks||[]).find(x=>x.profile_id===id);state.active=linked?.authority_state==='VERIFIED'&&['ACTIVE','ACTIVE_CANCELING','GRACE'].includes(String(me.membership?.status||''))&&me.membership?.profile_id===id&&me.membership?.access_state==='ACTIVE'&&me.membership?.rich_profile===true;return state.active}
 const input=(label,name,type='text')=>{const w=n('label');w.append(n('span',label));const i=document.createElement(type==='textarea'?'textarea':'input');if(type!=='textarea')i.type=type;i.name=name;i.id='r1365-'+name;if(type==='textarea')i.rows=4;w.htmlFor=i.id;w.append(i);return{w,i}};
 function isoLocal(value){if(!value)return'';const d=new Date(value);if(Number.isNaN(d.getTime()))return'';const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`}
 function toIso(value){if(!value)return'';const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toISOString()}
 function buildForm(){const box=n('section',undefined,'r1365-promo-editor');box.append(n('h3',state.editing?'Edit promotion or event':'Create a promotion or event'));
  const form=document.createElement('form');form.className='r1365-promo-form';
  const kind=input('Type','kind');kind.i=document.createElement('select');kind.i.name='kind';kind.i.id='r1365-kind';kind.w.replaceChildren(n('span','Type'),kind.i);for(const k of ['COUPON','SPECIAL','SALE','PROMOTION','EVENT']){const o=n('option',labels[k]);o.value=k;kind.i.append(o)}
  const title=input('Title','title'),desc=input('Description','description','textarea'),code=input('Coupon or offer code — optional','promoCode'),discount=input('Discount / value — optional','discountText'),url=input('Public action or redemption page — optional','actionUrl','url'),start=input('Start date/time — optional except events','startAt','datetime-local'),end=input('End / expiration date/time — optional','endAt','datetime-local'),where=input('Event location — events only','eventLocation');
  title.i.maxLength=180;desc.i.maxLength=1800;code.i.maxLength=80;discount.i.maxLength=160;where.i.maxLength=240;url.i.placeholder='https://';
  form.append(kind.w,title.w,desc.w,code.w,discount.w,url.w,start.w,end.w,where.w);
  const actions=n('div',undefined,'r37-member-actions'),save=n('button',state.editing?'Save changes':'Save draft','button primary');save.type='submit';actions.append(save);if(state.editing){const cancel=n('button','Cancel edit','button');cancel.type='button';cancel.onclick=()=>{state.editing=null;render()};actions.append(cancel)}form.append(actions);
  if(state.editing){const p=state.editing;kind.i.value=p.kind;title.i.value=p.title||'';desc.i.value=p.description||'';code.i.value=p.promo_code||p.promoCode||'';discount.i.value=p.discount_text||p.discountText||'';url.i.value=p.action_url||p.actionUrl||'';start.i.value=isoLocal(p.start_at||p.startAt);end.i.value=isoLocal(p.end_at||p.endAt);where.i.value=p.event_location||p.eventLocation||''}
  form.addEventListener('submit',e=>{e.preventDefault();work(async()=>{const payload={kind:kind.i.value,title:title.i.value.trim(),description:desc.i.value.trim(),promoCode:code.i.value.trim(),discountText:discount.i.value.trim(),actionUrl:url.i.value.trim(),startAt:toIso(start.i.value),endAt:toIso(end.i.value),eventLocation:where.i.value.trim()};if(state.editing){payload.promotionId=state.editing.promotion_id||state.editing.promotionId;payload.expectedRevision=Number(state.editing.revision);await req('/api/member/promotions/update?profileId='+enc(state.profileId),{method:'POST',body:payload});status('Promotion draft updated. Submit it for review when ready.','good')}else{await req('/api/member/promotions/create?profileId='+enc(state.profileId),{method:'POST',body:{...payload,idempotencyKey:crypto.randomUUID()}});status('Promotion draft saved.','good')}state.editing=null;await load()})});box.append(form);return box
 }
 function mediaFor(id){return state.media.filter(m=>(m.promotion_id||m.promotionId)===id)}
 function itemCard(p){const id=p.promotion_id||p.promotionId,card=n('article',undefined,'r1365-promo-card');card.append(n('div',(labels[p.kind]||p.kind)+' · '+p.state,'eyebrow'),n('h3',p.title),n('p',p.description));
  const meta=[];if(p.promo_code)meta.push('Code: '+p.promo_code);if(p.discount_text)meta.push(p.discount_text);if(p.start_at)meta.push('Starts '+new Date(p.start_at).toLocaleString());if(p.end_at)meta.push('Ends '+new Date(p.end_at).toLocaleString());if(p.event_location)meta.push(p.event_location);if(meta.length)card.append(n('p',meta.join(' · '),'fine-print'));if(p.public_reason)card.append(n('p',p.public_reason,'r37-status warn'));
  const actions=n('div',undefined,'r37-member-actions');if(['DRAFT','CHANGES_REQUESTED','UNPUBLISHED'].includes(p.state)){actions.append(button('Edit',()=>{state.editing=p;render();document.querySelector('.r1365-promo-editor')?.scrollIntoView({behavior:'smooth'})}));actions.append(button('Submit for review',()=>action('/api/member/promotions/submit',{promotionId:id},'Submitted for review.')))}if(p.state==='PUBLISHED')actions.append(button('Unpublish',()=>action('/api/member/promotions/unpublish',{promotionId:id},'Promotion unpublished.')));if(p.state!=='SUBMITTED')actions.append(button('Remove',()=>{if(confirm('Remove this promotion and its promotional media?'))return action('/api/member/promotions/remove',{promotionId:id},'Promotion removed.')}));card.append(actions);
  card.append(mediaEditor(p,mediaFor(id)));return card
 }
 const button=(text,fn)=>{const b=n('button',text,'button');b.type='button';b.onclick=fn;return b};
 async function action(path,body,msg){return work(async()=>{await req(path+'?profileId='+enc(state.profileId),{method:'POST',body});status(msg,'good');await load()})}
 function mediaEditor(p,rows){const id=p.promotion_id||p.promotionId,wrap=n('details',undefined,'r1365-media-editor'),sum=n('summary','Promotional graphic or flyer');wrap.append(sum);const body=n('div',undefined,'r1365-media-body');body.append(n('p','Upload one reviewed WebP image for a coupon, sale, promotion or event. Maximum 4 MB and 3000 × 3000. PDF upload is not supported.','fine-print'));
  for(const m of rows){const line=n('div',undefined,'r1365-media-row');line.append(n('span',(labels[m.media_kind]||m.media_kind)+' · '+m.state));if(m.public_reason)line.append(n('span',m.public_reason,'fine-print'));const a=n('div',undefined,'r37-member-actions');if(['DRAFT','CHANGES_REQUESTED'].includes(m.state))a.append(button('Submit image for review',()=>action('/api/member/promotions/media/submit',{promotionId:id,mediaId:m.media_id},'Image submitted for review.')));if(m.state!=='SUBMITTED')a.append(button('Remove image',()=>action('/api/member/promotions/media/remove',{promotionId:id,mediaId:m.media_id},'Image removed.')));line.append(a);body.append(line)}
  const form=document.createElement('form');form.className='r1365-media-form';const purpose=document.createElement('select');for(const k of ['COUPON_GRAPHIC','SALE_GRAPHIC','PROMOTIONAL_GRAPHIC','PROMOTIONAL_FLYER','EVENT_FLYER']){const o=n('option',labels[k]);o.value=k;purpose.append(o)}const file=document.createElement('input');file.type='file';file.accept='image/jpeg,image/png,image/webp';const rights=document.createElement('input');rights.type='checkbox';const rightsLabel=n('label');rightsLabel.append(rights,document.createTextNode(' I confirm I own this image or have permission to publish it.'));const upload=n('button','Upload image draft','button');upload.type='submit';form.append(n('label','Image purpose'),purpose,n('label','Choose image'),file,rightsLabel,upload);
  form.addEventListener('submit',e=>{e.preventDefault();work(async()=>{if(!file.files?.[0])throw new Error('Choose an image first.');if(!rights.checked)throw new Error('Confirm you have permission to publish this image.');const blob=await webp(file.files[0]);if(blob.size>4*1024*1024)throw new Error('Prepared image is still larger than 4 MB. Choose a smaller image.');const path='/api/member/promotions/media/upload?profileId='+enc(state.profileId)+'&promotionId='+enc(id)+'&mediaKind='+enc(purpose.value);const r=await fetch(API+path,{method:'POST',credentials:'include',cache:'no-store',headers:{'Content-Type':'image/webp','X-Franklin-Rights-Confirmed':'true'},body:blob});let out={};try{out=await r.json()}catch{}if(!r.ok)throw new Error(out?.message||out?.error?.message||'Image upload failed.');status('Image draft uploaded. Submit it for review when ready.','good');await load()})});body.append(form);wrap.append(body);return wrap
 }
 async function webp(file){if(file.type==='image/webp'&&file.size<=4*1024*1024)return file;const bmp=await createImageBitmap(file),scale=Math.min(1,3000/bmp.width,3000/bmp.height,Math.sqrt(9000000/(bmp.width*bmp.height))),w=Math.max(1,Math.round(bmp.width*scale)),h=Math.max(1,Math.round(bmp.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(bmp,0,0,w,h);bmp.close?.();return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('Your browser could not prepare this image.')),'image/webp',0.88))}
 async function load(){if(!await syncEligibility()){render();return}const [p,m]=await Promise.all([req('/api/member/promotions/list?profileId='+enc(state.profileId)),req('/api/member/promotions/media/list?profileId='+enc(state.profileId))]);state.promotions=p.promotions||[];state.media=m.media||[];render()}
 function render(){let box=panel();if(!box){box=n('section',undefined,'r1365-promotions-panel');box.dataset.r1365PromotionsPanel='1';root.append(box)}box.replaceChildren();box.append(n('div','Community Membership','eyebrow'),n('h2','Promotions & events'),n('p','Use your active Community Membership to publish reviewed coupons, specials, sales, limited-time promotions and events. These paid promotional tools are separate from your free profile-management rights.'));
  if(!state.active){box.append(n('p','An active Community Membership on this verified profile is required for promotions and promotional media. Free profile claiming, corrections, removal and approved profile photo/logo management remain available without membership.','r37-status'));box.append(n('a','Review Community Membership','button'));box.lastChild.href='/membership-start/';return}
  box.append(n('p','Published items automatically stop appearing after their end time. Promotional images require separate review. PDF flyers are not supported.','fine-print'),buildForm());const list=n('div',undefined,'r1365-promo-list');if(!state.promotions.length)list.append(n('p','No promotions or events yet. Save your first draft above.','fine-print'));else for(const p of state.promotions)list.append(itemCard(p));box.append(list)
 }
 async function work(fn){if(state.busy)return;state.busy=true;try{await fn()}catch(e){status(e.message||'We could not complete that request.','warn')}finally{state.busy=false}}
 function boot(){const wait=setInterval(()=>{const select=qs('#member-profile-selection');if(!select)return;clearInterval(wait);select.addEventListener('change',()=>{state.editing=null;work(load)});work(load)},250);setTimeout(()=>{clearInterval(wait);if(!panel())work(load)},6000)}
 document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot,{once:true}):boot();
})();